class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        total_area = sum(l * l for x, y, l in squares)
        target = total_area / 2.0

        def area_below(h):
            """Calculate total area of all squares below height h"""
            total = 0.0
            for x, y, l in squares:
                if h <= y:
                    # Entire square is above the line
                    continue
                elif h >= y + l:
                    # Entire square is below the line
                    total += l * l
                else:
                    # Partial square - only the part below h counts
                    total += l * (h - y)
            return total

        # Binary search for the y-coordinate where area_below == target
        left, right = 0.0, max(y + l for x, y, l in squares)

        while right - left > 1e-6:
            mid = (left + right) / 2.0
            if area_below(mid) < target:
                left = mid
            else:
                right = mid

        return (left + right) / 2.0

