class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def sum_steps(n):
            if n <= 0:
                return 0
            total = 0
            k = 1
            power = 1
            while power <= n:
                next_power = power * 4
                end = min(next_power - 1, n)
                total += k * (end - power + 1)
                k += 1
                power = next_power
            return total

        result = 0
        for l, r in queries:
            total_steps = sum_steps(r) - sum_steps(l - 1)
            operations = (total_steps + 1) // 2
            result += operations

        return result

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def sum_divisions(l, r):
            total = 0
            k = 0
            while 4 ** k <= r:
                start = 4 ** k
                end = 4 ** (k + 1) - 1
                left = max(l, start)
                right = min(r, end)
                if left <= right:
                    count = right - left + 1
                    total += count * (k + 1)
                k += 1
            return total

        total_ops = 0
        for l, r in queries:
            total_divisions = sum_divisions(l, r)
            total_ops += (total_divisions + 1) // 2

        return total_ops

