    def minOperations(self, queries: List[List[int]]) -> int:
        def sum_cost(r):
            if r <= 0:
                return 0
            total = 0
            cost = 1
            start = 1
            while start <= r:
                end = min(r, 4 ** cost - 1)
                count = end - start + 1
                total += cost * count
                start = 4 ** cost
                cost += 1
            return total

        total_ops = 0
        for l, r in queries:
            total_cost = sum_cost(r) - sum_cost(l - 1)
            ops = (total_cost + 1) // 2
            total_ops += ops

        return total_ops

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def sum_ops(l, r):
            total = 0
            k = 1
            while True:
                lower = 4 ** (k - 1)
                upper = 4 ** k - 1

                if lower > r:
                    break

                left = max(l, lower)
                right = min(r, upper)

                if left <= right:
                    count = right - left + 1
                    total += k * count

                k += 1

            return total

        total_ops = 0
        for l, r in queries:
            query_ops = sum_ops(l, r)
            total_ops += (query_ops + 1) // 2

        return total_ops

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def sum_divisions(l, r):
            total = 0
            k = 1
            while 4 ** (k - 1) <= r:
                range_start = 4 ** (k - 1)
                range_end = 4 ** k - 1

                inter_start = max(range_start, l)
                inter_end = min(range_end, r)

                if inter_start <= inter_end:
                    count = inter_end - inter_start + 1
                    total += count * k

                k += 1

            return total

        result = 0
        for l, r in queries:
            total_work = sum_divisions(l, r)
            result += (total_work + 1) // 2

        return result

