class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        import heapq
        n, m = len(moveTime), len(moveTime[0])
        dist = {}
        pq = [(0, 0, 0, 0)]  # (time, row, col, parity)

        while pq:
            time, r, c, parity = heapq.heappop(pq)

            if (r, c) == (n - 1, m - 1):
                return time

            if (r, c, parity) in dist:
                continue
            dist[(r, c, parity)] = time

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    start_time = max(time, moveTime[nr][nc])
                    move_cost = 1 if parity == 0 else 2
                    new_time = start_time + move_cost
                    new_parity = (parity + 1) % 2

                    if (nr, nc, new_parity) not in dist:
                        heapq.heappush(pq, (new_time, nr, nc, new_parity))

        return -1

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        import heapq

        n, m = len(moveTime), len(moveTime[0])
        pq = [(0, 0, 0, 0)]
        visited = set()

        while pq:
            t, x, y, parity = heapq.heappop(pq)

            if x == n - 1 and y == m - 1:
                return t

            if (x, y, parity) in visited:
                continue
            visited.add((x, y, parity))

            move_cost = 1 if parity == 0 else 2
            next_parity = 1 - parity

            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and (nx, ny, next_parity) not in visited:
                    earliest_time = max(t, moveTime[nx][ny])
                    new_time = earliest_time + move_cost
                    heapq.heappush(pq, (new_time, nx, ny, next_parity))

        return -1

