class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        result = []
        for g in groups:
            assigned = -1
            # Find the first element (smallest index) that divides the group size
            for j, e in enumerate(elements):
                if g % e == 0:
                    assigned = j
                    break
            result.append(assigned)
        return result

