class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def is_palindrome(text):
            return text == text[::-1]

        max_len = 0

        # Try all substrings from s and t
        for i in range(len(s) + 1):
            for j in range(i, len(s) + 1):
                for k in range(len(t) + 1):
                    for l in range(k, len(t) + 1):
                        combined = s[i:j] + t[k:l]
                        if is_palindrome(combined):
                            max_len = max(max_len, len(combined))

        return max_len

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)
        max_len = 0

        def is_palindrome(text):
            return text == text[::-1]

        # Pattern 1: prefix of s + suffix of t
        for i in range(n + 1):
            for j in range(m + 1):
                candidate = s[:i] + t[m-j:]
                if is_palindrome(candidate):
                    max_len = max(max_len, len(candidate))

        # Pattern 2: suffix of s + prefix of t
        for i in range(n + 1):
            for j in range(m + 1):
                candidate = s[n-i:] + t[:j]
                if is_palindrome(candidate):
                    max_len = max(max_len, len(candidate))

        return max_len

