                for k in range(len(t) + 1):
                    for l in range(k, len(t) + 1):
                        combined = s[i:j] + t[k:l]
                        # Check if it's a non-empty palindrome
                        if combined and combined == combined[::-1]:
                            max_len = max(max_len, len(combined))

        return max_len

