class Solution:
    def maximumTotalSum(self, maximumHeight: List[int]) -> int:
        maximumHeight.sort(reverse=True)

        total = 0
        current_height = float('inf')

        for max_h in maximumHeight:
            # Assign the maximum possible unique height
            assign_h = min(max_h, current_height - 1)

            if assign_h <= 0:
                return -1

            total += assign_h
            current_height = assign_h

        return total

class Solution:
    def maximumTotalSum(self, maximumHeight: List[int]) -> int:
        heights = sorted(maximumHeight, reverse=True)

        total = 0
        last_assigned = float('inf')

        for max_h in heights:
            h = min(max_h, last_assigned - 1)
            if h <= 0:
                return -1
            total += h
            last_assigned = h

        return total

