        def can_achieve(min_diff):
            # Sort intervals by start value
            intervals = sorted((start[i], start[i] + d) for i in range(len(start)))

            # Greedy: pick smallest value from first interval
            last_picked = intervals[0][0]

            for i in range(1, len(intervals)):
                # Next value must be at least last_picked + min_diff
                next_val = max(intervals[i][0], last_picked + min_diff)

                # Check if next_val is within the interval
                if next_val > intervals[i][1]:
                    return False

                last_picked = next_val

            return True

        # Binary search on the answer
        left, right = 0, 2 * 10**9
        answer = 0

