    def stringSequence(self, target: str) -> List[str]:
        result = []
        current = ""

        for i, char in enumerate(target):
            # First, extend the string to have enough length by appending 'a'
            while len(current) <= i:
                current += 'a'
                result.append(current)

            # Now increment the character at position i until it matches target[i]
            while current[i] != char:
                # Increment the character (wraps from 'z' to 'a')
                new_char = chr((ord(current[i]) - ord('a') + 1) % 26 + ord('a'))
                current = current[:i] + new_char + current[i+1:]
                result.append(current)

        return result

