            if not current or current[-1] != char:
                current += 'a'
                result.append(current)

            # Then, press key 2 to advance the last character to target char
            last_char = current[-1]
            while last_char != char:
                last_char = chr(ord(last_char) + 1) if last_char < 'z' else 'a'
