class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        result = []
        for y in nums:
            if y % 2 == 0:
                result.append(-1)
            else:
                # Count trailing 1s in y
                count = 0
                temp = y
                while temp & 1:
                    count += 1
                    temp >>= 1

                # x = y - (1 << (count - 1))
                x = y - (1 << (count - 1))
                result.append(x)

        return result

class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        result = []
        for num in nums:
            if num % 2 == 0:
                result.append(-1)
            else:
                candidates = set()
                candidates.add(num - 1)

                for i in range(32):
                    candidates.add(num ^ (1 << i))

                candidates.add(num >> 1)

                candidates = sorted([x for x in candidates if x >= 0 and x < num])
                min_x = -1
                for x in candidates:
                    if (x | (x + 1)) == num:
                        min_x = x
                        break

                result.append(min_x)

        return result

