        result = []
        for num in nums:
            found = False
            # For even numbers, no solution exists
            if num % 2 == 0:
                result.append(-1)
            else:
                # For odd numbers, search for minimum x where x | (x+1) == num
                for x in range(num):
                    if (x | (x + 1)) == num:
                        result.append(x)
                        found = True
                        break
                if not found:
                    result.append(-1)
        return result

