        ans = []
        for num in nums:
            min_x = float('inf')
            for k in range(num.bit_length() + 1):
                x = (num & (~((1 << (k + 1)) - 1))) | ((1 << k) - 1)
                if (x | (x + 1)) == num:
                    min_x = min(min_x, x)

            if min_x == float('inf'):
                ans.append(-1)
            else:
                ans.append(min_x)
        return ans

