    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        def count_ones_from_right(n):
            count = 0
            while n & 1:
                count += 1
                n >>= 1
            return count
        ans = []
        for n in nums:
            if n % 2 == 0:
                ans.append(-1)
            else:
                L = count_ones_from_right(n)
                if L == 1:
                    ans.append(n - 1)
                else:
                    ans.append((n >> L) << L | ((1 << (L - 1)) - 1))
        return ans

