class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = set(map(tuple, points))
        max_area = -1

        # Get unique x and y coordinates
        xs = sorted(set(p[0] for p in points))
        ys = sorted(set(p[1] for p in points))

        # Try all pairs of x and y coordinates
        for i in range(len(xs)):
            for j in range(i + 1, len(xs)):
                x1, x2 = xs[i], xs[j]
                for k in range(len(ys)):
                    for l in range(k + 1, len(ys)):
                        y1, y2 = ys[k], ys[l]

                        # Check if all 4 corners exist
                        if (x1, y1) in point_set and (x1, y2) in point_set and \
                           (x2, y1) in point_set and (x2, y2) in point_set:

                            # Check if no other point is inside or on the border
                            valid = True
                            for p in points:
                                px, py = p
                                # Check if point is inside or on the border
                                if x1 <= px <= x2 and y1 <= py <= y2:
                                    # Point should be one of the 4 corners
                                    if (px, py) not in [(x1, y1), (x1, y2), (x2, y1), (x2, y2)]:
                                        valid = False
                                        break

                            if valid:
                                area = (x2 - x1) * (y2 - y1)
                                max_area = max(max_area, area)

        return max_area

