                        p1, p2, p3, p4 = points[i], points[j], points[k], points[l]

                        xs = sorted([p1[0], p2[0], p3[0], p4[0]])
                        ys = sorted([p1[1], p2[1], p3[1], p4[1]])

                        if xs[0] == xs[1] and xs[2] == xs[3] and xs[0] != xs[2]:
                            if ys[0] == ys[1] and ys[2] == ys[3] and ys[0] != ys[2]:
                                x1, x2 = xs[0], xs[2]
                                y1, y2 = ys[0], ys[2]

                                corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}
                                if len(corners) == 4 and corners <= point_set:
                                    valid = True
                                    for p in points:
                                        if (p[0], p[1]) not in corners:
                                            if x1 <= p[0] <= x2 and y1 <= p[1] <= y2:
