class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def manhattan(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        def can_select(min_dist):
            n = len(points)

            def dfs(idx, selected):
                if len(selected) == k:
                    return True
                if idx == n:
                    return False
                if n - idx + len(selected) < k:
                    return False

                if all(manhattan(points[idx], points[j]) >= min_dist for j in selected):
                    selected.append(idx)
                    if dfs(idx + 1, selected):
                        return True
                    selected.pop()

                if dfs(idx + 1, selected):
                    return True

                return False

            return dfs(0, [])

        left, right = 0, 2 * side
        result = 0

        while left <= right:
            mid = (left + right) // 2
            if can_select(mid):
                result = mid
                left = mid + 1
            else:
                right = mid - 1

        return result

