class Solution:
    def minLargest(self, nums1: List[int], nums2: List[int]) -> int:
        def can_construct(max_val):
            evens = [i for i in range(2, max_val + 1, 2)]
            odds = [i for i in range(1, max_val + 1, 2)]

            count0_1, count1_1 = nums1.count(0), nums1.count(1)
            count0_2, count1_2 = nums2.count(0), nums2.count(1)

            if count0_1 + count0_2 > len(evens) or count1_1 + count1_2 > len(odds):
                return False

            def backtrack(arr_idx, pos_idx, last_val, used_evens, used_odds):
                if arr_idx == 2:
                    return True

                arr = nums1 if arr_idx == 0 else nums2
                if pos_idx == len(arr):
                    return backtrack(arr_idx + 1, 0, 0, used_evens, used_odds)

                val_type = arr[pos_idx]

                if val_type == 0:
                    for i, e in enumerate(evens):
                        if i not in used_evens and e > last_val:
                            used_evens.add(i)
                            if backtrack(arr_idx, pos_idx + 1, e, used_evens, used_odds):
                                used_evens.remove(i)
                                return True
                            used_evens.remove(i)
                else:
                    for i, o in enumerate(odds):
                        if i not in used_odds and o > last_val:
                            used_odds.add(i)
                            if backtrack(arr_idx, pos_idx + 1, o, used_evens, used_odds):
                                used_odds.remove(i)
                                return True
                            used_odds.remove(i)

                return False

            return backtrack(0, 0, 0, set(), set())

        left, right = 1, 4 * (len(nums1) + len(nums2))
        result = right

        while left <= right:
            mid = (left + right) // 2
            if can_construct(mid):
                result = mid
                right = mid - 1
            else:
                left = mid + 1

        return result

