    def minLargest(self, nums1: List[int], nums2: List[int]) -> int:
        def canConstruct(maxVal):
            evens = list(range(2, maxVal + 1, 2))
            odds = list(range(1, maxVal + 1, 2))

            n1, n2 = len(nums1), len(nums2)
            used = set()

            def solve(i1, i2, last1, last2):
                if i1 == n1 and i2 == n2:
                    return True

                if i1 < n1:
                    # Process nums1[i1]
                    if nums1[i1] == 0:
                        for e in evens:
                            if e not in used and e > last1:
                                used.add(e)
                                if solve(i1 + 1, i2, e, last2):
                                    return True
                                used.remove(e)
                    else:
                        for o in odds:
