        def can_assign(max_val):
            i1, i2 = 0, 0
            last1, last2 = 0, 0
            used = set()

            while i1 < len(nums1) or i2 < len(nums2):
                next_val1 = None
                next_val2 = None

                if i1 < len(nums1):
                    is_even = (nums1[i1] == 0)
                    # Find smallest value of correct parity > last1
                    start = max(last1 + 1, 2 if is_even else 1)
                    if is_even and start % 2 == 1:
                        start += 1
                    elif not is_even and start % 2 == 0:
                        start += 1

                    for val in range(start, max_val + 1, 2):
                        if val not in used:
                            next_val1 = val
                            break

                if i2 < len(nums2):
                    is_even = (nums2[i2] == 0)
                    # Find smallest value of correct parity > last2
                    start = max(last2 + 1, 2 if is_even else 1)
                    if is_even and start % 2 == 1:
                        start += 1
                    elif not is_even and start % 2 == 0:
                        start += 1

                    for val in range(start, max_val + 1, 2):
                        if val not in used:
                            next_val2 = val
                            break

                # Assign to the one that uses smaller value
                if next_val1 is not None and (next_val2 is None or next_val1 <= next_val2):
                    used.add(next_val1)
                    last1 = next_val1
                    i1 += 1
                elif next_val2 is not None:
                    used.add(next_val2)
                    last2 = next_val2
                    i2 += 1
                else:
                    return False

            return True

        # Binary search
