class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        stars = [i for i, c in enumerate(p) if c == '*']
        i1, i2 = stars[0], stars[1]

        part1 = p[:i1]
        part2 = p[i1+1:i2]
        part3 = p[i2+1:]

        min_len = float('inf')
        n = len(s)

        start_range = range(n - len(part1) + 1) if len(part1) > 0 else range(n + 1)

        for start in start_range:
            if len(part1) > 0 and s[start:start+len(part1)] != part1:
                continue

            pos_after_part1 = start + len(part1)

            if len(part2) > 0:
                for pos2 in range(pos_after_part1, n - len(part2) + 1):
                    if s[pos2:pos2+len(part2)] == part2:
                        pos_after_part2 = pos2 + len(part2)

                        if len(part3) > 0:
                            for pos3 in range(pos_after_part2, n - len(part3) + 1):
                                if s[pos3:pos3+len(part3)] == part3:
                                    end = pos3 + len(part3)
                                    min_len = min(min_len, end - start)
                                    break
                        else:
                            end = pos_after_part2
                            min_len = min(min_len, end - start)
                        break
            else:
                if len(part3) > 0:
                    for pos3 in range(pos_after_part1, n - len(part3) + 1):
                        if s[pos3:pos3+len(part3)] == part3:
                            end = pos3 + len(part3)
                            min_len = min(min_len, end - start)
                            break
                else:
                    end = pos_after_part1
                    min_len = min(min_len, end - start)

        return min_len if min_len != float('inf') else -1

