        parts = p.split('*')
        prefix, middle, suffix = parts[0], parts[1], parts[2]

        min_len = float('inf')

        for start in range(len(s) + 1):
            # Check if prefix matches at start
            if start + len(prefix) > len(s):
                continue
            if s[start:start + len(prefix)] != prefix:
                continue

            # Find first middle occurrence after prefix
            mid_pos = s.find(middle, start + len(prefix))
            if mid_pos == -1:
                continue

            # Find first suffix occurrence after middle
            suff_pos = s.find(suffix, mid_pos + len(middle))
            if suff_pos == -1:
                continue

            # Update minimum length
            length = suff_pos + len(suffix) - start
            min_len = min(min_len, length)

        return min_len if min_len != float('inf') else -1

