class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [{} for _ in range(n)]

        for i in range(n):
            dp[i][float('inf')] = 1

        for i in range(n):
            for j in range(i + 1, n):
                for prev_diff, length in dp[i].items():
                    new_diff = abs(nums[j] - nums[i])
                    if new_diff <= prev_diff:
                        if new_diff not in dp[j]:
                            dp[j][new_diff] = 0
                        dp[j][new_diff] = max(dp[j][new_diff], length + 1)

        max_length = 0
        for i in range(n):
            max_length = max(max_length, max(dp[i].values()))

        return max_length

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        from collections import defaultdict

        # dp[i][diff] = length of longest subsequence ending at nums[i] with last difference = diff
        dp = [defaultdict(int) for _ in range(len(nums))]

        for i in range(len(nums)):
            # Single element subsequence (use infinity to represent no previous difference)
            dp[i][float('inf')] = 1

            # Try extending from each previous element j
            for j in range(i):
                new_diff = abs(nums[i] - nums[j])

                # Extend from j if previous diff >= new diff
                for prev_diff, length in dp[j].items():
                    if prev_diff >= new_diff:
                        dp[i][new_diff] = max(dp[i][new_diff], length + 1)

        # Find maximum length
        result = 0
        for i in range(len(nums)):
            result = max(result, max(dp[i].values()))

        return result

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        # dp[i] is a dict: diff -> max_length
        # dp[i][d] = max length of subsequence ending at nums[i] with last absolute difference d
        dp = [{} for _ in range(n)]

        max_len = 1

        for i in range(n):
            # Start new sequence with just nums[i]
            dp[i][float('inf')] = 1

            # Try extending from all previous positions
            for j in range(i):
                new_diff = abs(nums[i] - nums[j])
                for last_diff, length in dp[j].items():
                    # Can extend if new difference is <= last difference
                    if new_diff <= last_diff:
                        if new_diff not in dp[i]:
                            dp[i][new_diff] = length + 1
                        else:
                            dp[i][new_diff] = max(dp[i][new_diff], length + 1)
                        max_len = max(max_len, dp[i][new_diff])

        return max_len

