            for j in range(i):
                diff = abs(nums[i] - nums[j])

                for prev_diff, length in dp[j].items():
                    if prev_diff >= diff:
                        if diff not in dp[i]:
                            dp[i][diff] = 0
                        dp[i][diff] = max(dp[i][diff], length + 1)
