class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        memo = {}

        def count_perms(o, e, next_is_odd):
            if (o, e, next_is_odd) in memo:
                return memo[(o, e, next_is_odd)]

            if o == 0 and e == 0:
                return 1

            if next_is_odd:
                if o == 0:
                    result = 0
                else:
                    result = o * count_perms(o - 1, e, False)
            else:
                if e == 0:
                    result = 0
                else:
                    result = e * count_perms(o, e - 1, True)

            memo[(o, e, next_is_odd)] = result
            return result

        def kth_perm(remaining_nums, k_val, last_is_odd):
            if len(remaining_nums) == 0:
                return []

            if last_is_odd is None:
                candidates = sorted(remaining_nums)
            else:
                if last_is_odd:
                    candidates = sorted([x for x in remaining_nums if x % 2 == 0])
                else:
                    candidates = sorted([x for x in remaining_nums if x % 2 == 1])

            for candidate in candidates:
                new_remaining = remaining_nums - {candidate}

                o = len([x for x in new_remaining if x % 2 == 1])
                e = len([x for x in new_remaining if x % 2 == 0])

                candidate_is_odd = candidate % 2 == 1

                if len(new_remaining) == 0:
                    count = 1
                else:
                    next_is_odd = not candidate_is_odd
                    count = count_perms(o, e, next_is_odd)

                if k_val <= count:
                    return [candidate] + kth_perm(new_remaining, k_val, candidate_is_odd)
                else:
                    k_val -= count

            return []

        remaining = set(range(1, n + 1))
        result = kth_perm(remaining, k, None)

        if len(result) == n:
            return result
        else:
            return []

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = [i for i in range(1, n+1) if i % 2 == 1]
        evens = [i for i in range(1, n+1) if i % 2 == 0]

        def is_alternating_possible(odds_left, evens_left):
            return len(odds_left) == len(evens_left) or abs(len(odds_left) - len(evens_left)) == 1

        def count_alternating(odds_left, evens_left):
            if is_alternating_possible(odds_left, evens_left):
                return math.factorial(len(odds_left)) * math.factorial(len(evens_left))
            else:
                return 0

        def dfs(odds, evens, k):
            if not odds and not evens:
                return []

            if not odds:
                k -= 1
                perm = []
                for i in range(len(evens)):
                    fact = math.factorial(len(evens) - 1 - i)
                    idx = k // fact if fact > 0 else 0
                    perm.append(evens[idx])
                    evens = evens[:idx] + evens[idx+1:]
                    k %= fact if fact > 0 else 1
                return perm

            if not evens:
                k -= 1
                perm = []
                for i in range(len(odds)):
                    fact = math.factorial(len(odds) - 1 - i)
                    idx = k // fact if fact > 0 else 0
                    perm.append(odds[idx])
                    odds = odds[:idx] + odds[idx+1:]
                    k %= fact if fact > 0 else 1
                return perm

            candidates = sorted([(v, 'O', i) for i, v in enumerate(odds)] + [(v, 'E', i) for i, v in enumerate(evens)])

            for val, parity, idx in candidates:
                if parity == 'O':
                    new_odds = odds[:idx] + odds[idx+1:]
                    count = count_alternating(new_odds, evens)
                else:
                    new_evens = evens[:idx] + evens[idx+1:]
                    count = count_alternating(odds, new_evens)

                if count > 0 and k <= count:
                    if parity == 'O':
                        return [val] + dfs(new_odds, evens, k)
                    else:
                        return [val] + dfs(odds, new_evens, k)

                k -= count

            return None

        if not is_alternating_possible(odds, evens):
            return []

        result = dfs(odds, evens, k)
        return result if result is not None else []

