    def permute(self, n: int, k: int) -> List[int]:
        odds = sorted([i for i in range(1, n+1) if i % 2 == 1])
        evens = sorted([i for i in range(1, n+1) if i % 2 == 0])

        num_odds = len(odds)
        num_evens = len(evens)

        if abs(num_odds - num_evens) > 1:
            return []

        result = []
        available_odds = set(odds)
        available_evens = set(evens)
        k -= 1

        for pos in range(n):
            if pos == 0:
                candidates = sorted(list(available_odds) + list(available_evens))
            else:
                if result[-1] % 2 == 1:
                    candidates = sorted(list(available_evens))
                else:
                    candidates = sorted(list(available_odds))

            found = False
            for candidate in candidates:
                if candidate % 2 == 1:
                    test_odds = available_odds - {candidate}
                    test_evens = available_evens
                else:
                    test_odds = available_odds
                    test_evens = available_evens - {candidate}

                if abs(len(test_odds) - len(test_evens)) > 1:
                    continue

                count = factorial(len(test_odds)) * factorial(len(test_evens))

                if k < count:
                    result.append(candidate)
                    if candidate % 2 == 1:
                        available_odds.remove(candidate)
                    else:
                        available_evens.remove(candidate)
                    found = True
                    break
                else:
                    k -= count

            if not found:
                return []

        return result

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = set(range(1, n + 1, 2))
        evens = set(range(2, n + 1, 2))

        result = []
        count = [0]

        def backtrack(current, remaining_odds, remaining_evens):
            if len(current) == n:
                count[0] += 1
                if count[0] == k:
                    result.extend(current)
                    return True
                return False

            if len(current) == 0:
                # Start with any number in sorted (lexicographical) order
                for num in range(1, n + 1):
                    if num % 2 == 1 and num in remaining_odds:
                        if backtrack(current + [num], remaining_odds - {num}, remaining_evens):
                            return True
                    elif num % 2 == 0 and num in remaining_evens:
                        if backtrack(current + [num], remaining_odds, remaining_evens - {num}):
                            return True
            else:
                last = current[-1]
                if last % 2 == 1:  # last is odd
                    # Next must be even
                    for even in sorted(remaining_evens):
                        if backtrack(current + [even], remaining_odds, remaining_evens - {even}):
                            return True
                else:  # last is even
                    # Next must be odd
                    for odd in sorted(remaining_odds):
                        if backtrack(current + [odd], remaining_odds - {odd}, remaining_evens):
                            return True

            return False

        if backtrack([], odds, evens):
            return result
        else:
            return []

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        import math

        def count_alternating(num_odds, num_evens, next_is_odd):
            # Count alternating permutations with given counts and starting parity
            if next_is_odd:
                # Pattern O E O E ..., need num_odds == num_evens or num_odds == num_evens + 1
                if num_odds != num_evens and num_odds != num_evens + 1:
                    return 0
            else:
                # Pattern E O E O ..., need num_evens == num_odds or num_evens == num_odds + 1
                if num_evens != num_odds and num_evens != num_odds + 1:
                    return 0
            return math.factorial(num_odds) * math.factorial(num_evens)

        result = []
        remaining_odds = list(range(1, n + 1, 2))
        remaining_evens = list(range(2, n + 1, 2))

        for position in range(n):
            if position == 0:
                # First position - can be odd or even
                odd_count = len(remaining_odds) * count_alternating(len(remaining_odds) - 1, len(remaining_evens), False)

                if k <= odd_count:
                    # Place an odd number
                    for odd_num in sorted(remaining_odds):
                        new_odd_count = len(remaining_odds) - 1
                        new_even_count = len(remaining_evens)
                        compl = count_alternating(new_odd_count, new_even_count, False)
                        if k <= compl:
                            result.append(odd_num)
                            remaining_odds.remove(odd_num)
                            break
                        k -= compl
                else:
                    k -= odd_count
                    # Place an even number
                    for even_num in sorted(remaining_evens):
                        new_odd_count = len(remaining_odds)
                        new_even_count = len(remaining_evens) - 1
                        compl = count_alternating(new_odd_count, new_even_count, True)
                        if k <= compl:
                            result.append(even_num)
                            remaining_evens.remove(even_num)
                            break
                        k -= compl
            else:
                # Subsequent positions - parity is determined
                last_parity = result[-1] % 2
                next_parity = 1 - last_parity

                if next_parity == 1:
                    # Next should be odd
                    for odd_num in sorted(remaining_odds):
                        new_odd_count = len(remaining_odds) - 1
                        new_even_count = len(remaining_evens)
                        compl = count_alternating(new_odd_count, new_even_count, False)
                        if k <= compl:
                            result.append(odd_num)
                            remaining_odds.remove(odd_num)
                            break
                        k -= compl
                else:
                    # Next should be even
                    for even_num in sorted(remaining_evens):
                        new_odd_count = len(remaining_odds)
                        new_even_count = len(remaining_evens) - 1
                        compl = count_alternating(new_odd_count, new_even_count, True)
                        if k <= compl:
                            result.append(even_num)
                            remaining_evens.remove(even_num)
                            break
                        k -= compl

        return result if k == 0 else []

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))

        # Check if alternating permutations are possible
        if abs(len(odds) - len(evens)) > 1:
            return []

        def count_alternating(num_odds, num_evens, start_with_odd):
            """Count alternating permutations with given counts, starting with specified parity"""
            if num_odds == 0 and num_evens == 0:
                return 1
            if start_with_odd:
                if num_odds == 0 or num_evens < num_odds - 1:
                    return 0
                return math.factorial(num_odds) * math.factorial(num_evens)
            else:
                if num_evens == 0 or num_odds < num_evens - 1:
                    return 0
                return math.factorial(num_odds) * math.factorial(num_evens)

        # Compute total alternating permutations
        if len(odds) == len(evens):
            total = 2 * math.factorial(len(odds)) * math.factorial(len(evens))
        else:
            total = math.factorial(max(len(odds), len(evens))) * math.factorial(min(len(odds), len(evens)))

        if k > total:
            return []

        result = []
        k_remaining = k
        curr_odds = odds[:]
        curr_evens = evens[:]

        for pos in range(n):
            # Determine candidates for the next position
            if pos == 0:
                # Can start with any number
                candidates = sorted(curr_odds + curr_evens)
            else:
                # Parity must alternate
                last_num = result[-1]
                if last_num % 2 == 1:  # Last was odd, next must be even
                    candidates = sorted(curr_evens)
                else:  # Last was even, next must be odd
                    candidates = sorted(curr_odds)

            # Try each candidate in lexicographical order
            found = False
            for candidate in candidates:
                # Compute the counts and next starting parity after this choice
                if candidate % 2 == 1:
                    new_num_odds = len(curr_odds) - 1
                    new_num_evens = len(curr_evens)
                    next_start_odd = False  # Next must be even
                else:
                    new_num_odds = len(curr_odds)
                    new_num_evens = len(curr_evens) - 1
                    next_start_odd = True  # Next must be odd

                count = count_alternating(new_num_odds, new_num_evens, next_start_odd)

                if count > 0:
                    if k_remaining <= count:
                        result.append(candidate)
                        if candidate % 2 == 1:
                            curr_odds.remove(candidate)
                        else:
                            curr_evens.remove(candidate)
                        found = True
                        break
                    else:
                        k_remaining -= count

            if not found:
                return []

        return result

