class Solution:
    def maxActiveSectionsAfterTrade(self, s: str, queries: List[List[int]]) -> List[int]:
        def count_ones(t):
            return t.count('1')

        def get_blocks(t):
            blocks = []
            i = 0
            while i < len(t):
                ch = t[i]
                j = i
                while j < len(t) and t[j] == ch:
                    j += 1
                blocks.append((ch, i, j))
                i = j
            return blocks

        results = []

        for l, r in queries:
            augmented = '1' + s[l:r+1] + '1'
            max_ones = count_ones(s[l:r+1])
            blocks = get_blocks(augmented)

            for remove_type, remove_start, remove_end in blocks:
                if remove_type != '1':
                    continue

                if remove_start == 0 or remove_end == len(augmented):
                    continue

                if not (augmented[remove_start - 1] == '0' and augmented[remove_end] == '0'):
                    continue

                temp_augmented = augmented[:remove_start] + '0' * (remove_end - remove_start) + augmented[remove_end:]
                temp_blocks = get_blocks(temp_augmented)

                for convert_type, convert_start, convert_end in temp_blocks:
                    if convert_type != '0':
                        continue

                    if not (convert_start > 0 and temp_augmented[convert_start - 1] == '1'):
                        continue
                    if not (convert_end < len(temp_augmented) and temp_augmented[convert_end] == '1'):
                        continue

                    traded_augmented = temp_augmented[:convert_start] + '1' * (convert_end - convert_start) + temp_augmented[convert_end:]
                    middle = traded_augmented[1:-1]
                    ones_count = count_ones(middle)
                    max_ones = max(max_ones, ones_count)

            results.append(max_ones)

        return results

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str, queries: List[List[int]]) -> List[int]:
        results = []

