class Solution:
    def maxSizedArray(self, s: int) -> int:
        def compute_or_sum(n):
            total = 0
            for bit in range(60):
                cycle = 1 << (bit + 1)
                count_with_bit = (n // cycle) * (1 << bit) + max(0, n % cycle - (1 << bit))
                count_without_bit = n - count_with_bit
                pairs_with_bit = n * n - count_without_bit * count_without_bit
                total += (1 << bit) * pairs_with_bit
            return total

        def compute_sum(n):
            if n == 0:
                return 0
            or_sum = compute_or_sum(n)
            return ((n - 1) * n // 2) * or_sum

        left, right = 0, 100000
        while left < right:
            mid = (left + right + 1) // 2
            if compute_sum(mid) <= s:
                left = mid
            else:
                right = mid - 1
        return left

class Solution:
    def maxSizedArray(self, s: int) -> int:
        def calculate_sum(n):
            if n <= 1:
                return 0

            # Calculate sum of all (j OR k) for j,k in [0, n-1]
            or_sum = 0
            for bit in range(60):
                power = 1 << bit
                if power >= 2*n:
                    break

                # Count numbers in [0, n-1] with this bit set
                cycle_len = power * 2
                full_cycles = n // cycle_len
                remainder = n % cycle_len

                count_set = full_cycles * power
                if remainder > power:
                    count_set += remainder - power

                # Pairs where this bit is set in at least one
                count_not_set = n - count_set
                pairs = n * n - count_not_set * count_not_set

                or_sum += power * pairs

            # Total sum = or_sum * (sum of i for i in [0, n-1])
            # = or_sum * n * (n-1) / 2
            return or_sum * n * (n - 1) // 2

        left, right = 0, 200000
        while left < right:
            mid = (left + right + 1) // 2
            if calculate_sum(mid) <= s:
                left = mid
            else:
                right = mid - 1
        return left

