    def maxProfit(self, workers: List[int], tasks: List[List[int]]) -> int:
        # Group tasks by skill requirement
        tasks_by_skill = defaultdict(list)
        for skill, profit in tasks:
            tasks_by_skill[skill].append(profit)

        # Sort tasks by profit (descending) for each skill
        for skill in tasks_by_skill:
            tasks_by_skill[skill].sort(reverse=True)

        # Count workers by skill level
        workers_by_skill = defaultdict(int)
        for skill in workers:
            workers_by_skill[skill] += 1

