        for skill in workers_by_skill:
            if skill in tasks_by_skill:
                num_workers = workers_by_skill[skill]
                tasks_list = tasks_by_skill[skill]

                # Match min(workers, tasks) with the best tasks
                matched_count = min(num_workers, len(tasks_list))
                for i in range(matched_count):
                    total_profit += tasks_list[i]

                # Track best unmatched task of this skill
                for i in range(matched_count, len(tasks_list)):
                    best_remaining = max(best_remaining, tasks_list[i])

        # For skills with no workers, all tasks are unmatched
        for skill in tasks_by_skill:
            if skill not in workers_by_skill or workers_by_skill[skill] == 0:
                best_remaining = max(best_remaining, tasks_by_skill[skill][0])

        # Additional worker takes the best remaining task
        total_profit += best_remaining
        return total_profit

