    def maxProfit(self, workers: List[int], tasks: List[List[int]]) -> int:
        from collections import defaultdict

        # Group workers by skill
        worker_count = defaultdict(int)
        for w in workers:
            worker_count[w] += 1

        # Sort tasks by profit descending
        tasks_sorted = sorted(tasks, key=lambda x: -x[1])

