class Solution:
    def maxTargetNodes(self, edges1: List[List[int]], edges2: List[List[int]], k: int) -> List[int]:
        from collections import deque, defaultdict

        def build_graph(edges):
            graph = defaultdict(list)
            for u, v in edges:
                graph[u].append(v)
                graph[v].append(u)
            return graph

        def count_targets(graph, start, k):
            visited = {start}
            queue = deque([(start, 0)])
            count = 1
            while queue:
                node, dist = queue.popleft()
                if dist < k:
                    for neighbor in graph[node]:
                        if neighbor not in visited:
                            visited.add(neighbor)
                            queue.append((neighbor, dist + 1))
                            count += 1
            return count

        def get_distances(graph, start, max_dist):
            distances = {start: 0}
            queue = deque([start])
            while queue:
                node = queue.popleft()
                if distances[node] < max_dist:
                    for neighbor in graph[node]:
                        if neighbor not in distances:
                            distances[neighbor] = distances[node] + 1
                            queue.append(neighbor)
            return distances

        graph1 = build_graph(edges1)
        graph2 = build_graph(edges2)

        n1 = len(edges1) + 1
        n2 = len(edges2) + 1

        tree2_counts = []
        for v in range(n2):
            distances_from_v = get_distances(graph2, v, k - 1)
            tree2_counts.append(len(distances_from_v))

        max_tree2_count = max(tree2_counts) if tree2_counts else 0

        answer = []
        for u in range(n1):
            targets_in_tree1 = count_targets(graph1, u, k)
            answer.append(targets_in_tree1 + max_tree2_count)

        return answer

