        def build_graph(edges, n):
            graph = defaultdict(list)
            for u, v in edges:
                graph[u].append(v)
                graph[v].append(u)
            return graph

        n = len(edges1) + 1
        m = len(edges2) + 1

        graph1 = build_graph(edges1, n)
        graph2 = build_graph(edges2, m)

        def count_nodes_within_distance(graph, start, max_dist):
            visited = set([start])
            queue = deque([(start, 0)])
            count = 1

            while queue:
                node, dist = queue.popleft()
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        if dist + 1 <= max_dist:
                            count += 1
                            queue.append((neighbor, dist + 1))

            return count

        count1 = []
        for i in range(n):
            count1.append(count_nodes_within_distance(graph1, i, k))

        max_count2 = 0
        for j in range(m):
            count2_j = count_nodes_within_distance(graph2, j, k - 1)
            max_count2 = max(max_count2, count2_j)

        answer = []
        for i in range(n):
            answer.append(count1[i] + max_count2)

        return answer

