class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count = 0

        for i in range(n):
            char_count = {}
            for j in range(i, n):
                # Add s[j] to the window
                char_count[s[j]] = char_count.get(s[j], 0) + 1

                # Check if any character appears >= k times
                if any(freq >= k for freq in char_count.values()):
                    # All substrings from i to j, i to j+1, ..., i to n-1 are valid
                    count += n - j
                    break

        return count

