class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))

        max_length = 0
        min_nodes = float('inf')

        def dfs(node, parent, length, num_nodes, seen_values, dup_count):
            nonlocal max_length, min_nodes

            if length > max_length or (length == max_length and num_nodes < min_nodes):
                max_length = length
                min_nodes = num_nodes

            for child, weight in adj[node]:
                if child == parent:
                    continue

                child_val = nums[child]
                new_dup_count = dup_count
                can_extend = False

                if child_val not in seen_values:
                    can_extend = True
                    new_seen = seen_values | {child_val}
                elif dup_count == 0:
                    can_extend = True
                    new_seen = seen_values | {child_val}
                    new_dup_count = 1
                else:
                    can_extend = False

                if can_extend:
                    dfs(child, node, length + weight, num_nodes + 1, new_seen, new_dup_count)

        for start in range(n):
            dfs(start, -1, 0, 1, {nums[start]}, 0)

        return [max_length, min_nodes]

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]

        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        children = [[] for _ in range(n)]
        visited = [False] * n

        def build_rooted_tree(node):
            visited[node] = True
            for child, weight in graph[node]:
                if not visited[child]:
                    children[node].append((child, weight))
                    build_rooted_tree(child)

        build_rooted_tree(0)

        max_length = [0]
        min_nodes = [float('inf')]

        def dfs(node, value_count, dup_count, path_length, path_nodes):
            if path_length > 0:
                if path_length > max_length[0]:
                    max_length[0] = path_length
                    min_nodes[0] = path_nodes
                elif path_length == max_length[0] and path_nodes < min_nodes[0]:
                    min_nodes[0] = path_nodes

            for child, weight in children[node]:
                child_val = nums[child]
                old_count = value_count.get(child_val, 0)
                new_dup_count = dup_count

                if old_count == 1:
                    new_dup_count += 1

                if new_dup_count <= 1:
                    value_count[child_val] = old_count + 1
                    dfs(child, value_count, new_dup_count, path_length + weight, path_nodes + 1)
                    if old_count == 0:
                        del value_count[child_val]
                    else:
                        value_count[child_val] = old_count

        for start in range(n):
            dfs(start, {nums[start]: 1}, 0, 0, 1)

        if max_length[0] == 0:
            return [0, 1]
        return [max_length[0], min_nodes[0]]

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        adj = [[] for _ in range(n)]

        for u, v, length in edges:
            adj[u].append((v, length))
            adj[v].append((u, length))

        max_length = 0
        min_nodes = float('inf')

        def dfs(node, parent, current_len, current_nodes, value_count):
            nonlocal max_length, min_nodes

            num_duplicates = sum(1 for cnt in value_count.values() if cnt > 1)
            if num_duplicates <= 1:
                if current_len > max_length:
                    max_length = current_len
                    min_nodes = current_nodes
                elif current_len == max_length and current_nodes < min_nodes:
                    min_nodes = current_nodes

            if num_duplicates > 1:
                return

            for child, edge_len in adj[node]:
                if child == parent:
                    continue

                child_val = nums[child]
                value_count[child_val] = value_count.get(child_val, 0) + 1

                dfs(child, node, current_len + edge_len, current_nodes + 1, value_count)

                value_count[child_val] -= 1
                if value_count[child_val] == 0:
                    del value_count[child_val]

        for start in range(n):
            dfs(start, -1, 0, 1, {nums[start]: 1})

        return [max_length, min_nodes]

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]

        for u, v, length in edges:
            adj[u].append((v, length))
            adj[v].append((u, length))

        result = [0, 1]

        def dfs(node, parent, freq, has_dup, path_len):
            nonlocal result

            value = nums[node]

            if value in freq:
                freq[value] += 1
                if freq[value] > 2 or (freq[value] == 2 and has_dup):
                    freq[value] -= 1
                    return
            else:
                freq[value] = 1

            new_has_dup = has_dup or (freq[value] == 2)
            num_nodes = len(freq)

            if path_len > result[0]:
                result[0] = path_len
                result[1] = num_nodes
            elif path_len == result[0]:
                result[1] = min(result[1], num_nodes)

            for neighbor, edge_len in adj[node]:
                if neighbor != parent:
                    dfs(neighbor, node, freq, new_has_dup, path_len + edge_len)

            freq[value] -= 1
            if freq[value] == 0:
                del freq[value]

        for start in range(n):
            dfs(start, -1, {}, False, 0)

        return result

