class Solution:
    def minConnectedGroups(self, intervals: List[List[int]], k: int) -> int:
        intervals.sort()

        # Merge overlapping intervals to find groups
        merged = []
        for start, end in intervals:
            if merged and start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])

        if len(merged) == 1:
            return 1

        max_gaps_closed = 0

        # Try all contiguous subsequences of gaps
        for i in range(len(merged) - 1):
            for j in range(i, len(merged) - 1):
                # Can we bridge gaps from i to j with a single interval?
                gap_start = merged[i][1]
                gap_end = merged[j + 1][0]
                needed_length = gap_end - gap_start

                if needed_length <= k:
                    gaps_closed = j - i + 1
                    max_gaps_closed = max(max_gaps_closed, gaps_closed)

        return len(merged) - max_gaps_closed

