class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        result = [row[:] for row in grid]

        # Bottom-left triangle (i >= j), sorted in non-increasing order
        # Diagonals identified by i - j
        for diff in range(n):
            diagonal = []
            positions = []
            for i in range(n):
                j = i - diff
                if 0 <= j < n:
                    diagonal.append(result[i][j])
                    positions.append((i, j))

            diagonal.sort(reverse=True)

            for (i, j), val in zip(positions, diagonal):
                result[i][j] = val

        # Top-right triangle (i < j), sorted in non-decreasing order
        # Diagonals identified by j - i
        for diff in range(1, n):
            diagonal = []
            positions = []
            for i in range(n):
                j = i + diff
                if 0 <= j < n:
                    diagonal.append(result[i][j])
                    positions.append((i, j))

            diagonal.sort()

            for (i, j), val in zip(positions, diagonal):
                result[i][j] = val

        return result

