    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        result = [row[:] for row in grid]

        # Process each diagonal
        for d in range(-(n-1), n):
            diagonal = []
            positions = []

            if d >= 0:
                # Bottom-left triangle (including main diagonal)
                for i in range(d, n):
                    j = i - d
                    diagonal.append(grid[i][j])
                    positions.append((i, j))
            else:
                # Top-right triangle
                for j in range(-d, n):
                    i = j + d
                    diagonal.append(grid[i][j])
                    positions.append((i, j))

            # Sort diagonal
            if d >= 0:
                diagonal.sort(reverse=True)  # Non-increasing
            else:
                diagonal.sort()  # Non-decreasing

            # Put sorted values back
            for idx, (i, j) in enumerate(positions):
                result[i][j] = diagonal[idx]

        return result

