            for j in range(n):
                d = i - j
                if d not in diagonals:
                    diagonals[d] = []
                diagonals[d].append(grid[i][j])

        # Sort diagonals: d >= 0 (bottom-left) non-increasing, d < 0 (top-right) non-decreasing
        for d in diagonals:
            if d >= 0:
                diagonals[d].sort(reverse=True)
            else:
                diagonals[d].sort()

        # Place sorted values back into result matrix
