class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)

        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]
            prefix_cost[i + 1] = prefix_cost[i] + cost[i]

        INF = float('inf')
        dp = [[INF] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(i):
                for num_sub in range(j + 1):
                    if dp[j][num_sub] == INF:
                        continue
                    subarray_index = num_sub + 1
                    subarray_cost = (prefix_sum[i] + k * subarray_index) * (prefix_cost[i] - prefix_cost[j])
                    dp[i][num_sub + 1] = min(dp[i][num_sub + 1], dp[j][num_sub] + subarray_cost)

        return min(dp[n][1:])

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)

        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]
            prefix_cost[i + 1] = prefix_cost[i] + cost[i]

        # dp[i][j] = min cost to partition nums[0..i-1] into j subarrays
        INF = float('inf')
        dp = [[INF] * (n + 2) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(1, i + 1):
                # Try all positions for the start of the j-th subarray
                for prev in range(j - 1, i):
                    if dp[prev][j - 1] < INF:
                        # Cost of subarray nums[prev..i-1]
                        # Formula: (sum from 0 to i-1 + k*j) * (cost_sum from prev to i-1)
                        subarray_cost = (prefix_sum[i] + k * j) * (prefix_cost[i] - prefix_cost[prev])
                        dp[i][j] = min(dp[i][j], dp[prev][j - 1] + subarray_cost)

        # Find minimum cost for any valid partition
        ans = INF
        for j in range(1, n + 1):
            ans = min(ans, dp[n][j])
        return ans

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)

        # Precompute prefix sums
        prefix_nums = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)
        for i in range(n):
            prefix_nums[i + 1] = prefix_nums[i] + nums[i]
            prefix_cost[i + 1] = prefix_cost[i] + cost[i]

        # dp[i][m] = min cost to divide nums[0:i] into m subarrays
        INF = float('inf')
        dp = [[INF] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for m in range(1, i + 1):
                for j in range(m - 1, i):
                    # Subarray from index j to i-1
                    num_sum = prefix_nums[i]
                    cost_sum = prefix_cost[i] - prefix_cost[j]
                    subarray_cost = (num_sum + k * m) * cost_sum
                    dp[i][m] = min(dp[i][m], dp[j][m - 1] + subarray_cost)

        # Find minimum cost across all possible number of subarrays
        return min(dp[n][1:])

