minimum-operations-to-make-elements-with.code:
class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)

        def cost(i, j):
            subarray = sorted(nums[i:j])
            median = subarray[len(subarray) // 2]
            return sum(abs(val - median) for val in subarray)

        INF = float('inf')
        dp = [[INF] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(k + 1):
                dp[i][j] = dp[i-1][j]

                if j > 0 and i >= x:
                    c = cost(i - x, i)
                    dp[i][j] = min(dp[i][j], dp[i-x][j-1] + c)

        return dp[n][k]

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)

        def get_cost(subarray):
            sorted_arr = sorted(subarray)
            median = sorted_arr[len(subarray) // 2]
            return sum(abs(val - median) for val in subarray)

        INF = float('inf')
        dp = [[INF] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(k + 1):
                dp[i][j] = dp[i-1][j]

                if i >= x and j > 0:
                    subarray = nums[i-x:i]
                    cost = get_cost(subarray)
                    dp[i][j] = min(dp[i][j], dp[i-x][j-1] + cost)

        return dp[n][k]

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)

        def get_cost(start):
            if start + x > n:
                return float('inf')
            subarray = sorted(nums[start:start + x])
            target = subarray[x // 2]
            return sum(abs(num - target) for num in nums[start:start + x])

        INF = float('inf')
        dp = [[INF] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(k + 1):
                dp[i][j] = dp[i-1][j]

                if j > 0 and i >= x:
                    cost_val = get_cost(i - x)
                    if cost_val != INF:
                        dp[i][j] = min(dp[i][j], dp[i-x][j-1] + cost_val)

        return dp[n][k]

