class Solution:
    def checkValidCuts(self, n: int, rectangles: List[List[int]]) -> bool:
        def can_cut(intervals):
            intervals.sort()

            merged = []
            for start, end in intervals:
                if merged and start < merged[-1][1]:
                    merged[-1] = (merged[-1][0], max(merged[-1][1], end))
                else:
                    merged.append((start, end))

            return len(merged) >= 3

        y_intervals = [(ry1, ry2) for _, ry1, _, ry2 in rectangles]
        x_intervals = [(rx1, rx2) for rx1, _, rx2, _ in rectangles]

        return can_cut(y_intervals) or can_cut(x_intervals)

