            """Check if we can make horizontal cuts at y=cut1 and y=cut2"""
            # cut1 < cut2, partitions into 3 sections: y < cut1, cut1 <= y < cut2, y >= cut2
            section_count = [0, 0, 0]

            for rect in rectangles:
                sx, sy, ex, ey = rect
                # Check which section this rectangle belongs to
                if ey <= cut1:
                    section_count[0] += 1
                elif sy >= cut2:
                    section_count[2] += 1
                elif sy >= cut1 and ey <= cut2:
                    section_count[1] += 1
                else:
                    # Rectangle spans multiple sections - invalid cut
                    return False

            # All three sections must have at least one rectangle
            return all(count > 0 for count in section_count)

        def can_cut_vertical(cut1, cut2):
