                        if r3 != r and c3 != c1 and c3 != c2:
                            max_sum = max(max_sum, v1 + v2 + v3)
                            break

        # Try pairs of cells from the same column
        for c in range(n):
            for i in range(len(top_in_col[c])):
                for j in range(i + 1, len(top_in_col[c])):
