class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        result = []

        for i in range(n):
            # Remove index i
            remaining = words[:i] + words[i+1:]

            if len(remaining) < k:
                result.append(0)
                continue

            # Binary search on LCP length
            left, right = 0, min(len(w) for w in remaining)
            ans = 0

            while left <= right:
                mid = (left + right) // 2
                # Check if there exist k strings with common prefix of length mid
                if self._can_find_k_with_prefix(remaining, k, mid):
                    ans = mid
                    left = mid + 1
                else:
                    right = mid - 1

            result.append(ans)

        return result

    def _can_find_k_with_prefix(self, words: List[str], k: int, prefix_len: int) -> bool:
        from collections import defaultdict
        prefix_count = defaultdict(int)

        for word in words:
            prefix = word[:prefix_len]
            prefix_count[prefix] += 1
            if prefix_count[prefix] >= k:
                return True

        return False

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        answer = []

        for i in range(n):
            remaining = words[:i] + words[i+1:]

            if len(remaining) < k:
                answer.append(0)
                continue

            class TrieNode:
                def __init__(self):
                    self.children = {}
                    self.count = 0

            root = TrieNode()

            for word in remaining:
                node = root
                for char in word:
                    if char not in node.children:
                        node.children[char] = TrieNode()
                    node = node.children[char]
                    node.count += 1

            def dfs(node):
                if node.count < k:
                    return 0
                max_child_depth = 0
                for child in node.children.values():
                    max_child_depth = max(max_child_depth, dfs(child))
                return 1 + max_child_depth

            length = 0
            for child in root.children.values():
                length = max(length, dfs(child))

            answer.append(length)

        return answer

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        def find_max_prefix_for_k(remaining_words, k):
            if len(remaining_words) < k:
                return 0

            max_len = max(len(w) for w in remaining_words)

            for prefix_len in range(max_len, 0, -1):
                prefixes = set()
                for word in remaining_words:
                    if len(word) >= prefix_len:
                        prefixes.add(word[:prefix_len])

                for prefix in prefixes:
                    count = sum(1 for w in remaining_words if w.startswith(prefix))
                    if count >= k:
                        return prefix_len

            return 0

        result = []
        for i in range(len(words)):
            remaining = words[:i] + words[i+1:]
            result.append(find_max_prefix_for_k(remaining, k))

        return result

