class Solution:
    def stringHash(self, s: str, k: int) -> str:
        result = []
        for i in range(0, len(s), k):
            chunk = s[i:i+k]
            hash_sum = sum(ord(c) - ord('a') for c in chunk)
            hashed_char = hash_sum % 26
            result.append(chr(ord('a') + hashed_char))
        return ''.join(result)

