class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        memo = {}

        def dp(pair_idx, left_prev_color, right_prev_color):
            # pair_idx: which pair we're processing (0 to n/2 - 1)
            # left_prev_color: color of house to left of current left house
            # right_prev_color: color of house to right of current right house

            if pair_idx == n // 2:
                return 0

            left_idx = pair_idx
            right_idx = n - 1 - pair_idx

            if (pair_idx, left_prev_color, right_prev_color) in memo:
                return memo[(pair_idx, left_prev_color, right_prev_color)]

            res = float('inf')

            for left_color in range(3):
                # Check adjacent constraint for left house
                if left_idx > 0 and left_color == left_prev_color:
                    continue

                for right_color in range(3):
                    # Check pair constraint: left and right must differ
                    if left_color == right_color:
                        continue

                    # Check adjacent constraint for right house
                    if right_idx < n - 1 and right_color == right_prev_color:
                        continue

                    res = min(res, cost[left_idx][left_color] + cost[right_idx][right_color] + 
                             dp(pair_idx + 1, left_color, right_color))

            memo[(pair_idx, left_prev_color, right_prev_color)] = res
            return res

        return dp(0, -1, -1)

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        dp = [[[INF] * 3 for _ in range(3)] for _ in range(n // 2)]

        for c1 in range(3):
            for c2 in range(3):
                if c1 != c2:
                    dp[0][c1][c2] = cost[0][c1] + cost[n-1][c2]

        for i in range(1, n // 2):
            for c1 in range(3):
                for c2 in range(3):
                    if c1 == c2:
                        continue

                    for prev_c1 in range(3):
                        for prev_c2 in range(3):
                            if prev_c1 == c1 or prev_c2 == c2:
                                continue

                            dp[i][c1][c2] = min(dp[i][c1][c2], 
                                                 dp[i-1][prev_c1][prev_c2] + cost[i][c1] + cost[n-1-i][c2])

        result = min(dp[n//2 - 1][c1][c2] for c1 in range(3) for c2 in range(3))
        return result

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        memo = {}

        def solve(index, colors_so_far):
            if index == n:
                for i in range(n // 2):
                    if colors_so_far[i] == colors_so_far[n - 1 - i]:
                        return float('inf')
                return 0

            key = (index, colors_so_far)
            if key in memo:
                return memo[key]

            result = float('inf')
            for color in range(3):
                if index > 0 and colors_so_far[index - 1] == color:
                    continue

                mirror = n - 1 - index
                if mirror < index and colors_so_far[mirror] == color:
                    continue

                new_colors = colors_so_far + (color,)
                result = min(result, cost[index][color] + solve(index + 1, new_colors))

            memo[key] = result
            return result

        res = solve(0, ())
        return res if res < float('inf') else 0

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i, prev_color, pair_colors):
            if i == n:
                return 0

            result = float('inf')
            pair_idx = n - 1 - i

            for c in range(3):
                # Adjacent constraint
                if c == prev_color:
                    continue

                # Pair constraint
                if pair_idx < len(pair_colors) and pair_colors[pair_idx] == c:
                    continue

                # Update pair_colors for next iteration
                if i < n // 2:
                    new_pair_colors = pair_colors + (c,)
                else:
                    new_pair_colors = pair_colors

                result = min(result, cost[i][c] + dp(i + 1, c, new_pair_colors))

            return result

        return dp(0, -1, ())

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')

        # dp[c1][c2] = min cost where house i has color c1, house n-1-i has color c2
        dp = [[INF] * 3 for _ in range(3)]

        # Base case: i = 0, houses 0 and n-1
        for c1 in range(3):
            for c2 in range(3):
                if c1 != c2:
                    dp[c1][c2] = cost[0][c1] + cost[n-1][c2]

        # Process pairs from outside in
        for i in range(1, n // 2):
            new_dp = [[INF] * 3 for _ in range(3)]
            j = n - 1 - i

            for c1 in range(3):
                for c2 in range(3):
                    if c1 == c2:  # Mirror constraint
                        continue

                    # Try all previous states
                    for prev_c1 in range(3):
                        for prev_c2 in range(3):
                            if prev_c1 == c1 or prev_c2 == c2:  # Adjacent constraints
                                continue

                            if dp[prev_c1][prev_c2] < INF:
                                new_dp[c1][c2] = min(new_dp[c1][c2], 
                                                      dp[prev_c1][prev_c2] + cost[i][c1] + cost[j][c2])

            dp = new_dp

        return min(min(row) for row in dp)

