        m = n // 2
        INF = float('inf')
        dp = [[[INF] * 3 for _ in range(3)] for _ in range(m)]

        for c1 in range(3):
            for c2 in range(3):
                if c1 != c2:
                    dp[0][c1][c2] = cost[0][c1] + cost[n-1][c2]

        for i in range(1, m):
            left_house = i
            right_house = n - 1 - i

            for c1 in range(3):
                for c2 in range(3):
                    if c1 == c2:
                        continue

                    for prev_c1 in range(3):
                        for prev_c2 in range(3):
                            if prev_c1 == c1 or prev_c2 == c2:
                                continue
                            if dp[i-1][prev_c1][prev_c2] != INF:
                                dp[i][c1][c2] = min(dp[i][c1][c2],
                                                    dp[i-1][prev_c1][prev_c2] + cost[left_house][c1] + cost[right_house][c2])

        result = INF
        for c1 in range(3):
            for c2 in range(3):
                result = min(result, dp[m-1][c1][c2])

        return result

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # dp[(c1, c2)] = min cost where current pair has colors (c1, c2)
        pairs = [(i, n - 1 - i) for i in range(n // 2)]

        # Initialize for first pair (0, n-1)
        dp = {}
        for c1 in range(3):
            for c2 in range(3):
                if c1 != c2:
                    dp[(c1, c2)] = cost[0][c1] + cost[n-1][c2]

        # Process pairs from 1 to n/2 - 1
        for pair_idx in range(1, n // 2):
            left_idx, right_idx = pairs[pair_idx]
            prev_left_idx, prev_right_idx = pairs[pair_idx - 1]

            new_dp = {}

            for (prev_c1, prev_c2), prev_cost in dp.items():
                for c1 in range(3):
                    for c2 in range(3):
                        # Constraints:
                        # c1 != c2 (equidistant constraint)
                        # c1 != prev_c1 (adjacent to previous left)
                        # c2 != prev_c2 (adjacent to previous right)
                        if c1 != c2 and c1 != prev_c1 and c2 != prev_c2:
                            key = (c1, c2)
                            new_cost = prev_cost + cost[left_idx][c1] + cost[right_idx][c2]
                            if key not in new_dp or new_dp[key] > new_cost:
                                new_dp[key] = new_cost

            dp = new_dp

        return min(dp.values())

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        dp = {}
        for j in range(3):
            for k in range(3):
                if j != k:
                    dp[(j, k)] = cost[0][j] + cost[n-1][k]

        for i in range(1, n // 2):
            new_dp = {}
            for (prev_j, prev_k), prev_cost in dp.items():
                for j in range(3):
                    for k in range(3):
                        if j != prev_j and k != prev_k and j != k:
                            key = (j, k)
                            new_cost = prev_cost + cost[i][j] + cost[n-1-i][k]
                            if key not in new_dp:
                                new_dp[key] = new_cost
                            else:
                                new_dp[key] = min(new_dp[key], new_cost)
