class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        # finish[i] = time when wizard i finishes their current work
        finish = [0] * n

        for j in range(m):
            new_finish = [0] * n
            for i in range(n):
                if i == 0:
                    # First wizard starts when they're free
                    start = finish[i]
                else:
                    # Later wizards wait for potion to arrive or for themselves to be free
                    start = max(new_finish[i-1], finish[i])

                time_taken = skill[i] * mana[j]
                new_finish[i] = start + time_taken

            finish = new_finish

        return finish[n-1]

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        def computeTime(order):
            end_time = [[0] * m for _ in range(n)]
            for j, potion_idx in enumerate(order):
                for i in range(n):
                    prev_wizard = end_time[i][j-1] if j > 0 else 0
                    prev_potion = end_time[i-1][j] if i > 0 else 0
                    end_time[i][j] = max(prev_wizard, prev_potion) + skill[i] * mana[potion_idx]
            return end_time[n-1][m-1]

        min_time_result = float('inf')

        def backtrack(used_mask, order):
            nonlocal min_time_result

            if used_mask == (1 << m) - 1:
                total_time = computeTime(order)
                min_time_result = min(min_time_result, total_time)
                return

            current_max = float('inf')
            if order:
                temp_end = [[0] * len(order) for _ in range(n)]
                for j, potion_idx in enumerate(order):
                    for i in range(n):
                        prev_wizard = temp_end[i][j-1] if j > 0 else 0
                        prev_potion = temp_end[i-1][j] if i > 0 else 0
                        temp_end[i][j] = max(prev_wizard, prev_potion) + skill[i] * mana[potion_idx]
                current_max = temp_end[n-1][-1]

            if current_max >= min_time_result:
                return

            for potion_idx in range(m):
                if used_mask & (1 << potion_idx):
                    continue

                backtrack(used_mask | (1 << potion_idx), order + [potion_idx])

        backtrack(0, [])
        return min_time_result

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        mana_sorted = sorted(mana)

        wizard_done_time = [0] * len(skill)

        for m in mana_sorted:
            for i in range(len(skill)):
                if i == 0:
                    start_time = wizard_done_time[0]
                else:
                    start_time = max(wizard_done_time[i], wizard_done_time[i - 1])

                wizard_done_time[i] = start_time + skill[i] * m

        return wizard_done_time[-1]

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        from functools import lru_cache

        m = len(mana)
        n = len(skill)

        @lru_cache(maxsize=None)
        def dp(used_mask, wizard_free_times):
            if used_mask == (1 << m) - 1:
                return max(wizard_free_times)

            result = float('inf')

            for potion_idx in range(m):
                if used_mask & (1 << potion_idx):
                    continue

                new_times = list(wizard_free_times)
                current_time = new_times[0]

                for wizard_idx in range(n):
                    if wizard_idx > 0:
                        current_time = max(current_time, new_times[wizard_idx])
                    current_time += skill[wizard_idx] * mana[potion_idx]
                    new_times[wizard_idx] = current_time

                result = min(result, dp(used_mask | (1 << potion_idx), tuple(new_times)))

            return result

        return dp(0, tuple([0] * n))

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        depart = [[0] * m for _ in range(n)]

        # Compute prefix sums for easier calculation
        prefix_sum = [[0] * m for _ in range(n)]
        for j in range(m):
            for i in range(n):
                if i == 0:
                    prefix_sum[i][j] = skill[i] * mana[j]
                else:
                    prefix_sum[i][j] = prefix_sum[i-1][j] + skill[i] * mana[j]

        # Potion 0
        depart[0][0] = skill[0] * mana[0]
        for i in range(1, n):
            depart[i][0] = depart[i-1][0] + skill[i] * mana[0]

        # Potions 1 to m-1
        for j in range(1, m):
            # Determine start_time[j]
            start_time = depart[0][j-1]  # Can't start before finishing potion j-1 with wizard 0

            # Apply order constraint: at each wizard, potions must be processed in order
            for i in range(1, n):
                raw_processing_time = prefix_sum[i-1][j]
                min_start = depart[i][j-1] - raw_processing_time
                start_time = max(start_time, min_start)

            # Compute depart values for potion j
            depart[0][j] = start_time + skill[0] * mana[j]
            for i in range(1, n):
                depart[i][j] = max(depart[i-1][j], depart[i][j-1]) + skill[i] * mana[j]

        return depart[n-1][m-1]

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        done = [0] * n

        for j in range(m):
            done[0] += skill[0] * mana[j]
            for i in range(1, n):
                done[i] = max(done[i], done[i-1]) + skill[i] * mana[j]

        return done[n-1]

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        min_time = float('inf')

        for order_fn in [lambda j: mana[j], lambda j: -mana[j]]:
            order = sorted(range(m), key=order_fn)

            finish = [0] * n
            for j in order:
                for i in range(n):
                    if i == 0:
                        start = finish[0]
                    else:
                        start = max(finish[i-1], finish[i])
                    finish[i] = start + skill[i] * mana[j]

            min_time = min(min_time, finish[n-1])

        return min_time
